import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import { forwardRef, type ComponentRef, type CSSProperties } from 'react';
import { normalizeClassName } from '@/lib/moduix/normalizeClassName';
import styles from './AspectRatio.module.css';

type AspectRatioRootProps = HTMLArkProps<'div'> & {
  ratio: number;
};

const AspectRatioRoot = forwardRef<ComponentRef<typeof ark.div>, AspectRatioRootProps>(
  function AspectRatioRoot({ ratio, className, style, ...props }, ref) {
    if (!Number.isFinite(ratio) || ratio <= 0) {
      throw new RangeError('AspectRatio `ratio` must be a finite number greater than zero.');
    }

    return (
      <ark.div
        {...props}
        ref={ref}
        data-scope="aspect-ratio"
        data-part="root"
        data-slot="aspect-ratio-root"
        className={clsx(styles.root, normalizeClassName(className))}
        style={{ ...style, '--_aspect-ratio-value': ratio } as CSSProperties}
      />
    );
  },
);

const AspectRatio = Object.assign(AspectRatioRoot, {
  Root: AspectRatioRoot,
});

export { AspectRatio };

@layer moduix.components {
  .root {
    --_aspect-ratio-value: 1;
    position: relative;
    box-sizing: border-box;
    display: block;
    width: 100%;
    aspect-ratio: var(--_aspect-ratio-value);
    overflow: hidden;
    border-radius: var(--moduix-aspect-ratio-radius, var(--moduix-radius-md));

    & > :where(img, video, iframe, canvas, svg) {
      box-sizing: border-box;
      display: block;
      width: 100%;
      height: 100%;
    }

    & > iframe {
      border: 0;
    }
  }
}
